import { useState, useEffect } from "react";

export default function Hmes() {

  const text = "Oujda City";     // النص لي بغيتي يتكتب
  const [display, setDisplay] = useState("");

  useEffect(() => {
    let index = 0;
    const interval = setInterval(() => {
      if (index < text.length) {
        setDisplay(prev => prev + text[index]);
        index++;
      } else {
        clearInterval(interval);
      }
    }, 150);   // السرعة (نقصيها ولا زيديها)
    return () => clearInterval(interval);
  }, []);

  return (
    <>
      <style>{`
        h1{
          color:#4b2e14;
          font-size:70px;
          font-weight:900;
          text-align:center;
          margin-top:40vh;
          letter-spacing:3px;
        }

        .cursor{
          border-right:4px solid #4b2e14;
          animation: blink .7s infinite;
        }

        @keyframes blink{
          50%{ border-color:transparent; }
        }
      `}</style>

      <h1>
        <span className="cursor">{display}</span>
      </h1>
    </>
  );
}
